from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bands=[]
    in_band=False
    for r,row in enumerate(grid):
        active=any(v!=bg for v in row)
        if active and not in_band:
            start=r; in_band=True
        if in_band and (not active or r==h-1):
            end = r if not active else r+1
            bands.append((start,end)); in_band=False
    if len(bands)<2:
        return [row[:] for row in grid]
    (a0,a1),(b0,b1)=bands[0],bands[1]
    n=min(a1-a0,b1-b0)
    if n<=0:
        return [row[:] for row in grid]
    max_shift=min(5,w-1)
    best_dx=0; best_score=-1
    for dx in range(-max_shift,max_shift+1):
        score=0
        for rr in range(n):
            ar,br=grid[a0+rr],grid[b0+rr]
            for x in range(w):
                y=x+dx
                if 0<=y<w and ar[x]==br[y]:
                    score+=1
        if score>best_score:
            best_dx,best_score=dx,score
    out=[row[:] for row in grid]
    for rr in range(n):
        ar,br=a0+rr,b0+rr
        for x in range(w):
            y=x+best_dx
            if not 0<=y<w: continue
            av,bv=grid[ar][x],grid[br][y]
            if av!=bg and bv==bg:
                out[br][y]=1
            elif bv!=bg and av==bg:
                out[ar][x]=1
    return out

