source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    bands = []
    active_start = None
    for r, row in enumerate(grid):
        active = any(value != background for value in row)
        if active and active_start is None:
            active_start = r
        elif not active and active_start is not None:
            bands.append((active_start, r))
            active_start = None
    if active_start is not None:
        bands.append((active_start, h))
    if len(bands) < 2:
        return [row[:] for row in grid]

    (top, top_end), (bottom, bottom_end) = bands[:2]
    height = min(top_end - top, bottom_end - bottom)
    if height == 0:
        return [row[:] for row in grid]

    best_shift, best_score = 0, -1
    for shift in range(-min(5, w - 1), min(5, w - 1) + 1):
        score = 0
        for offset in range(height):
            upper = grid[top + offset]
            lower = grid[bottom + offset]
            for x in range(w):
                y = x + shift
                if 0 <= y < w and upper[x] == lower[y]:
                    score += 1
        if score > best_score:
            best_shift, best_score = shift, score

    result = [row[:] for row in grid]
    for offset in range(height):
        upper_r, lower_r = top + offset, bottom + offset
        for x in range(w):
            y = x + best_shift
            if not 0 <= y < w:
                continue
            upper_value = grid[upper_r][x]
            lower_value = grid[lower_r][y]
            if upper_value != background and lower_value == background:
                result[lower_r][y] = 1
            elif lower_value != background and upper_value == background:
                result[upper_r][x] = 1
    return result
